import type { Argv, ArgumentsCamelCase, CommandModule } from 'yargs'
import { credentialProvider } from '../../auth'
import { validateWorkingDir } from '../../util'
import { cwd } from 'process'
import { logger } from '../../logger'
import * as fs from 'fs'
import { createTelemetryClient } from '../../telemetry'
import { Orchestrator, Project } from '@servicenow/sdk-api'
import { NowConfig } from '@servicenow/sdk-build-core'

interface Arguments {
    directory: string
    auth: string | undefined
    typeDefsOnly?: boolean
    fluentOnly?: boolean
    add?: string
    scope?: string
    sysIds?: string[]
}

export const dependencies: CommandModule<unknown, Arguments> = {
    command: 'dependencies [sysIds..]',
    //biome-ignore format: intentionally bad formatting
    describe: 'Download configured dependencies in now.config.json and typescript type definitions for use in the application',
    builder: (yargs: Argv) => {
        return yargs
            .positional('sysIds', {
                describe: 'System IDs to add when using --add flag',
                type: 'string',
                array: true,
            })
            .option('directory', {
                describe: `Path to the directory that contains package.json configuration`,
                default: cwd(),
                type: 'string',
            })
            .option('auth', {
                describe: 'Credential alias to use for authentication with instance',
                type: 'string',
                alias: 'a',
            })
            .option('type-defs-only', {
                describe: 'Download only script type definitions (glide.*.d.ts)',
                type: 'boolean',
            })
            .option('fluent-only', {
                describe: 'Download only fluent types from now.config.json dependencies',
                type: 'boolean',
            })
            .option('add', {
                describe: 'Add new dependency items (table name, e.g., actions, triggers, sys_security_acl)',
                type: 'string',
                requiresArg: true,
            })
            .option('scope', {
                describe: 'Scope for dependencies (e.g., global, x_my_app). Required when using --add',
                type: 'string',
            })
            .conflicts('type-defs-only', 'fluent-only')
            .check((argv) => {
                if (argv.add) {
                    if (!argv.sysIds || argv.sysIds.length === 0) {
                        throw new Error('--add requires at least one sys_id or "*"')
                    }
                    if (!argv.scope) {
                        throw new Error('--add requires --scope flag (e.g., --scope global)')
                    }
                    if (argv['type-defs-only'] || argv['fluent-only']) {
                        throw new Error('--add cannot be used with --type-defs-only or --fluent-only')
                    }
                }
                return true
            }) as Argv<Arguments>
    },
    handler: async (args: ArgumentsCamelCase<Arguments>): Promise<void> => {
        const { add } = args

        if (add) {
            await handleAddDependency(args, add)
        } else {
            await handleDownloadDependencies(args)
        }
    },
}

async function createOrchestratorContext(args: ArgumentsCamelCase<Arguments>) {
    const credential = await credentialProvider(args.auth)
    const workingDir = validateWorkingDir(args.directory)
    const config = NowConfig.parseFromDirectory(workingDir, fs, logger)
    const telemetryClient = createTelemetryClient(fs, __dirname, credential.getUrl())

    const project = new Project({
        config,
        fileSystem: fs,
        rootDir: workingDir,
        logger,
        transformMode: 'type-generation',
        telemetryClient,
    })

    const orchestrator = new Orchestrator(project, credential)

    return { orchestrator }
}

async function handleAddDependency(args: ArgumentsCamelCase<Arguments>, type: string): Promise<void> {
    const ids = args.sysIds || []
    const scope = args.scope

    // Scope is validated as required in the check() function
    if (!scope) {
        throw new Error('Scope is required but was not provided')
    }

    logger.info(`Adding ${ids.length} ${type} to project (scope: ${scope})...`)

    try {
        const { orchestrator } = await createOrchestratorContext(args)
        await orchestrator.addDependency({
            table: type,
            ids,
            scope,
        })
        logger.info(`✓ Successfully added ${ids.length} ${type}`)
    } catch (error) {
        logger.error(`Failed to add ${type}:`, error)
    }
}

async function handleDownloadDependencies(args: ArgumentsCamelCase<Arguments>): Promise<void> {
    const { typeDefsOnly, fluentOnly } = args

    // Determine what to download
    const downloadScripts = typeDefsOnly || (!typeDefsOnly && !fluentOnly)
    const downloadFluent = fluentOnly || (!typeDefsOnly && !fluentOnly)

    logger.info('Fetching application dependencies from instance...')

    try {
        const { orchestrator } = await createOrchestratorContext(args)
        await orchestrator.types({
            downloadScripts,
            downloadFluent,
        })
    } catch (error) {
        logger.error(`Failed to fetch dependencies`, error)
    }
}
